def solar_escape_v_inf():
    """Heliocentric hyperbolic excess needed for solar escape from 1 AU (prograde)."""
    v_orb = math.sqrt(GM_SUN / AU)          # Earth's heliocentric circular speed
    v_esc = math.sqrt(2.0 * GM_SUN / AU)    # local solar escape speed
    return math.sqrt(v_esc ** 2 - v_orb ** 2)

